import * as React from "react";

import { FrameScope } from "../lib/frame-context";
import { cn } from "../lib/utils";
import { Button } from "./button";
import { Icon } from "./icon";
import { Skeleton } from "./skeleton";
import { Spinner } from "./spinner";

import styles from "./settings-card.module.css";

export type SettingsCardProps = Omit<
  React.ComponentPropsWithoutRef<"section">,
  "title" | "onSubmit"
> & {
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: React.ReactNode;
  dirty?: boolean;
  onSave?: () => void | Promise<unknown>;
  onDiscard?: () => void;
  hint?: React.ReactNode;
  locked?: React.ReactNode;
  loading?: boolean;
  saveLabel?: string;
  /** Blocks Save and says why, the way Button's disabledReason does: the button stays focusable and shows the reason on hover and focus. */
  saveDisabledReason?: string;
  tone?: "default" | "danger";
  actions?: React.ReactNode;
  /** Renders the body edge to edge without the form and footer, for content that is not saved here, such as an embedded DataTable. */
  flush?: boolean;
};

export function SettingsCard({
  title,
  description,
  action,
  dirty = false,
  onSave,
  onDiscard,
  hint,
  locked,
  loading = false,
  saveLabel = "Save",
  saveDisabledReason,
  tone = "default",
  actions,
  flush = false,
  children,
  className,
  ref,
  ...props
}: SettingsCardProps & { ref?: React.Ref<HTMLElement> }) {
  const [saving, setSaving] = React.useState(false);
  const titleId = React.useId();
  const save = async () => {
    if (!onSave || !dirty || saving || locked || saveDisabledReason) return;
    setSaving(true);
    try {
      await onSave();
    } catch {
      // The caller reports the failure with a toast; the card only keeps what was typed.
    } finally {
      setSaving(false);
    }
  };
  let status: React.ReactNode = hint;
  if (locked)
    status = (
      <>
        <Icon name="lock" size={14} />
        {locked}
      </>
    );
  else if (saving)
    status = (
      <>
        <Spinner />
        Saving
      </>
    );
  else if (dirty)
    status = (
      <>
        <span className={styles.dirtyMark} aria-hidden="true" />
        Unsaved changes
      </>
    );
  const header = (
    <div className={styles.header}>
      <div className={styles.copy}>
        <h3 id={titleId} className={styles.title}>
          {title}
        </h3>
        {description && <p className={styles.description}>{description}</p>}
      </div>
      {action && <div className={styles.action}>{action}</div>}
    </div>
  );
  const body = loading ? <Skeleton lines={2} height={32} /> : children;
  const hasBody = loading || React.Children.toArray(children).length > 0;
  if (flush)
    return (
      <section
        ref={ref}
        data-slot="settings-card"
        data-tone={tone}
        data-flush=""
        aria-labelledby={titleId}
        className={cn(styles.card, className)}
        {...props}
      >
        {header}
        {hasBody && (
          <FrameScope framed>
            <div className={styles.flushContent}>{body}</div>
          </FrameScope>
        )}
      </section>
    );
  return (
    <section
      ref={ref}
      data-slot="settings-card"
      data-tone={tone}
      aria-labelledby={titleId}
      className={cn(styles.card, className)}
      {...props}
    >
      <form
        noValidate
        onSubmit={(event) => {
          event.preventDefault();
          save();
        }}
      >
        {header}
        {hasBody && (
          <FrameScope framed>
            <fieldset className={styles.content} disabled={Boolean(locked) || saving}>
              {body}
            </fieldset>
          </FrameScope>
        )}
        <div className={styles.footer}>
          <p className={styles.status} role="status">
            {status}
          </p>
          {!locked && (
            <div className={styles.buttons}>
              {tone === "danger" ? (
                actions
              ) : (
                <>
                  {dirty && onDiscard && !saving && (
                    <Button type="button" variant="ghost" size="sm" onClick={onDiscard}>
                      Discard
                    </Button>
                  )}
                  {onSave && (
                    <Button
                      type="submit"
                      variant="primary"
                      size="sm"
                      disabled={!saveDisabledReason && (!dirty || loading)}
                      disabledReason={saveDisabledReason}
                      loading={saving}
                    >
                      {saveLabel}
                    </Button>
                  )}
                </>
              )}
            </div>
          )}
        </div>
      </form>
    </section>
  );
}
SettingsCard.displayName = "SettingsCard";

.card {
  min-width: 0;
  overflow: hidden;
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: 0;
  background: var(--v4-surface);
  color: var(--v4-ink);
}
.card[data-tone="danger"] {
  border-color: var(--v4-bad-line);
}
.header {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  padding: var(--v4-space-surface-inset) var(--v4-space-surface-inset) 0;
}
.copy {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--v4-space-4);
  min-width: 0;
}
.title {
  margin: 0;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
.description {
  margin: 0;
  color: var(--v4-text2);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.action {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-8);
}
.content {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-field-group);
  min-width: 0;
  margin: 0;
  padding: var(--v4-space-16) var(--v4-space-surface-inset) var(--v4-space-surface-inset);
  border: 0;
}
.card[data-flush] > .header {
  padding-bottom: var(--v4-space-16);
}
.flushContent {
  min-width: 0;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.content > [data-slot="field"],
.content > [data-slot="input"] {
  max-width: var(--v4-size-measure-field);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-height: calc(var(--v4-size-control-sm) + 2 * var(--v4-space-12));
  padding: var(--v4-space-12) var(--v4-space-12) var(--v4-space-12) var(--v4-space-surface-inset);
  border-top: 1px solid var(--v4-line-soft);
  background: var(--v4-paper);
}
.card[data-tone="danger"] .footer {
  border-top-color: var(--v4-bad-line);
  background: var(--v4-bad-wash);
}
.status {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  margin: 0;
  color: var(--v4-text2);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.dirtyMark {
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--v4-warn);
}
.buttons {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-12);
}
